import json
from pathlib import Path
r=Path('content/base-reviewed.json');p=json.loads(r.read_text(encoding='utf8'));b={x['id']:x for x in p}
def update(id,**fields):
 b[id].update(fields)
 for q in b[id]['quiz']:q['ruleHint']=b[id]['connection']
def question(id,question,options,reasons,translation):
 q=b[id]['quiz'][0];q.update(question=question,options=options,correctIndex=0,translation=translation,explanations=[dict(text=o,isCorrect=i==0,reason=reasons[i]) for i,o in enumerate(options)])
update('g1-l1-time-and-age',nuance='Hours: 四時よじ、七時しちじ、九時くじ. Minutes include 一分いっぷん、三分さんぷん、四分よんぷん、六分ろっぷん、八分はっぷん、十分じゅっぷん／じっぷん. Ages include 一歳いっさい、八歳はっさい、十歳じゅっさい／じっさい and 二十歳はたち. 何時なんじ asks the time; 何歳なんさい or おいくつ asks age. 半 after the hour means half past. Learn the actual counter reading rather than deriving it mechanically from the independent number.')
b['g1-l1-time-and-age']['quiz'][0]['explanations'][2]['reason']='四時 has the conventional reading よじ. The general number reading し does not carry over to this counter combination; do not invent an etymological reason.'
b['g1-l1-question-ka']['quiz'][0]['explanations'][1]['reason']='でした is a past statement ending, not the present question ですか.'
update('g1-l3-masenka-invitation',nuance='ませんか is a standard polite invitation; it does not inherently imply a date. It can also be a literal negative question, so use context. ましょう suggests proceeding together or accepts an invitation. When declining politely, Japanese often gives a reason or trails off with ちょっと rather than using a blunt refusal.')
update('g1-l11-tai-desire',meaning='Want to do an action; たくない means not want to do it.',nuance='Attach たい to the polite stem, then conjugate as an い-adjective: 食べたい、食べたくない、食べたかった. In an ordinary statement this commonly expresses the speaker\'s own desire, while a question can ask the listener\'s desire. Third-person desire usually needs evidence/reporting or another appropriate context, such as 食べたがっている or 食べたいと言っている. The object can take を or が in suitable constructions. Wanting something does not itself mean a plan or commitment.',connection='Vます-stem + たい / たくない / たかった')
update('g1-l11-koto-ga-aru',meaning='Have done something before; have had an experience.',nuance='Vたことがある presents a previous occurrence as an experience relevant now; it is not restricted to a life-changing or once-in-a-lifetime event. For a simple report of what you did this morning, use a past sentence instead. The time span can be limited by context. V dictionary + ことがある is a different pattern meaning sometimes do. 一度も + negative emphasizes never.',keyTakeaway='たことがある = have done before; dictionary form + ことがある = sometimes do.')
update('g1-l11-sugiru',nuance='すぎる means exceeding a suitable degree or amount. It often describes an undesirable excess, but can also be enthusiastic hyperbole, as in おいしすぎる. Attach to the verb stem, the い-adjective stem, or the な-adjective stem. いい becomes よすぎる. The basic negative adjective ない becomes なさすぎる; negative verb combinations need care rather than applying one mechanical rule to every ない.',keyTakeaway='Stem + すぎる; いい→よすぎる. The resulting expression conjugates as a ru-verb.')
update('g1-l12-node-objective-reason',title='〜ので (Reason / Background Circumstance)',meaning='Because; since. Presents a reason or background circumstance.',nuance='ので often makes a reason sound explanatory and less assertive, including before a polite request. から can also be polite, and ので does not make a claim objectively true. Plain non-past nouns and な-adjectives use な: 雨なので、静かなので. Other endings retain their form: 雨だったので、静かではないので. Polite forms can also occur before ので in polite speech.',keyTakeaway='N/な-adjective non-past affirmative: なので. Choose the register and reason in context.')
update('gp-kara-node',title='〜から vs 〜ので (Reasons & Background)',meaning='Both give reasons; ので often presents background more gently, while から readily supports the speaker\'s decision.')
update('gp-dake-shika',title='〜だけ vs 〜しか〜ない (Limitation & Exclusion)')
update('genki1-te-iru',nuance='ている can describe an action in progress, a resulting state, or a repeated activity depending on the verb and context. 結婚している usually means is married; 住んでいる describes living somewhere. 知っている means know, and the ordinary negative answer is 知りません. This is the beginner default, not a prohibition against every contextual use of 知っていない. Do not assume that every verb with ている translates as English is doing.',keyTakeaway='Choose the meaning from the verb and context: ongoing action, resulting state, or repetition.')
update('genki1-ndesu',nuance='んです connects the statement to relevant background, an observed situation or a request for explanation. A plain factual statement such as 頭が痛いです is normal; it is not inherently cold or medical. 頭が痛いんです presents the headache as explanatory in context. Overusing んです can sound as if every statement requires justification, and んですか can sound probing. Nouns and な-adjectives use なんです only in their non-past affirmative form; past and negative forms keep their endings.')
update('gp-toki',meaning='When; at the time a situation holds or an event occurs.',nuance='With a bounded action, dictionary-form とき commonly locates the main event before completion, while たとき commonly locates it after completion. Compare 日本へ行くとき買った and 日本へ行ったとき買った. This is a relative-time contrast, not a rule that every たとき refers to a finished event: 困ったとき means when in trouble, and 子供だったとき means when I was a child. Interpret tense together with the predicate\'s meaning and the surrounding situation.',keyTakeaway='Use relative timing and the type of situation; とき is not mechanically before versus after.')
question('g1-l2-kore-sore-are-dore','指さした物について質問します。「（　　）は誰の傘ですか。」',['これ','この','ここで','ここに'],['これ stands alone and refers to the indicated object.','この requires a following noun; このは is not this construction.','ここで marks an action location and cannot identify an umbrella here.','ここに marks a location of existence, not the indicated object.'],'Pointing at an object: Whose umbrella is this?')
question('g1-l2-kono-sono-ano-dono','「その辞書」の意味になる形を選んでください。すみません、（　　）辞書を見せてください。',['その','それ','そこ','そのの'],['その directly modifies 辞書.','それ is a standalone pronoun.','そこ means a place and does not directly modify 辞書.','その already modifies a noun; do not add の.'],'Choose the form meaning that dictionary: Please show me that dictionary.')
question('g1-l12-deshou-darou','田中さんはよく勉強していますから、明日の試験に（　　）でしょう。',['合格する','合格して','合格し','合格するだ'],['The dictionary form connects directly to でしょう.','The te-form does not connect directly to でしょう here.','The bare stem does not form the required predicate.','Do not put だ after a finite verb before でしょう.'],'Tanaka studies hard, so they will probably pass tomorrow\'s exam.')
question('gp-dake-shika','「千円だけ持っています」と同じ金額を表します。千円（　　）持っていません。',['しか','だけを','だけが','だけに'],['しか with a negative predicate expresses only one thousand yen.','だけを with this negative would deny holding that particular amount rather than say it is all one has.','だけが cannot mark the possessed object of 持つ here.','だけに is not the object/exclusion construction needed here.'],'Express the same amount as I have only one thousand yen.')
r.write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
